head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[footer > P > excelCellType]<br/>advancedExcelDownload() 메소드로 GridView 의 데이터를 Excel 로 다운로드 시 Footer 의 Excel 표시 형식을 설정합니다.",
    "validation" : [
        "Footer 의 excelCellType 속성값은 참고용으로 사용되며 Excel 다운로드 시 Footer Column 의 excelCellType 속성이 적용됩니다.",
        "text 설정 시, Footer 의 Excel 표시 형식을 '텍스트' 로 설정합니다.",
        "number 설정 시, Footer 의 Excel 표시 형식을 '숫자' 로 설정합니다.",
        "bigDecimal 설정 시, Footer 의 Excel 표시 형식을 '숫자' 로 설정합니다.",
        "date 설정 시, Footer 의 Excel 표시 형식을 '날짜' 로 설정합니다.",
        "Footer Column 의 excelCellType 속성값은 advancedExcelDownload() 메소드의 options.useDataFormat 파라미터값이 'true' 일때 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_excelCellType.setValue("number");
    con_columnExcelCellType.setValue("text");
    par_useDataFormat.setValue("true");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - excelCellType 은 dynamic N 이므로 렌더 시점에만 설정한다.
    let cExcelCellType = con_excelCellType.getValue();
    let cColumnExcelCellType = con_columnExcelCellType.getValue();
    let lblFooter = (cExcelCellType === '') ? '미설정' : cExcelCellType;
    let lblColumn = (cColumnExcelCellType === '') ? '미설정' : cColumnExcelCellType;
    let attrFooter = (cExcelCellType === '') ? '' : ' excelCellType="' + cExcelCellType + '"';
    let attrColumn = (cColumnExcelCellType === '') ? '' : ' excelCellType="' + cColumnExcelCellType + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] GridView 하위에 w2:footer 를 선언하고 Footer 4개 Column 의 값은 8002.3 으로 고정, 대비를 위해 w2:footer 와 Footer Column 에 서로 다른 excelCellType 을 설정\n[현재] footer excelCellType = ' + lblFooter + ' / footer column excelCellType = ' + lblColumn + '\n[절차] 옵션 변경 후 Target 재생성 -> options.useDataFormat 선택 -> advancedExcelDownload 버튼 클릭\n[확인] 다운로드한 xlsx 는 서버가 표시 문자열을 재파싱하고 displayFormat 을 서식으로 적용하여 차이를 볼 수 없으므로, 메소드 호출 구간에만 form submit 을 가로채 서버로 전송되는 XML 에 실린 값으로 확인함 (실제 다운로드는 그대로 진행됨)"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (footer 포함)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:700px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1"' + attrFooter + '>';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col1" value="8002.3"' + attrColumn + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col2" value="8002.3"' + attrColumn + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col3" value="8002.3"' + attrColumn + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col4" value="8002.3"' + attrColumn + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 다운로드 요청 캡처 : 서버로 전송되는 값을 확인하기 위해 메소드 호출 구간에서만
//  form submit 과 XHR send 를 감싸고 호출 직후 원복한다. (실제 요청은 그대로 통과시킨다.)
scwin.hookRequest = function () {
    let objReq = { "kind" : "", "body" : "" };
    scwin.gVar.req = objReq;

    let fnSubmit = HTMLFormElement.prototype.submit;
    let fnSend = XMLHttpRequest.prototype.send;

    HTMLFormElement.prototype.submit = function () {
        if (objReq.kind === "") {
            objReq.kind = "Form Submit";
            let objInput = this.querySelector("input[name=xmlValue]");
            objReq.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function (vData) {
        if (objReq.kind === "") {
            objReq.kind = "XHR";
            objReq.body = vData + "";
        }
        return fnSend.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
        XMLHttpRequest.prototype.send = fnSend;
    };
}



// 캡처한 요청 본문에서 hashkey 로 전송된 옵션값을 읽는다.
scwin.getSentValue = function (sKey) {
    let sBody = (scwin.gVar.req === undefined) ? "" : (scwin.gVar.req.body || "");
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// 여는 태그 문자열에서 속성값을 읽는다. (속성이 없으면 미설정)
scwin.getAttrValue = function (sTag, sName) {
    let nKey = sTag.indexOf(" " + sName + "=");
    if (nKey < 0) {
        return "(미설정)";
    }
    let sRest = sTag.substring(nKey + sName.length + 2);
    let sQuote = sRest.charAt(0);
    sRest = sRest.substring(1);
    let nEnd = sRest.indexOf(sQuote);
    return (nEnd < 0) ? "(미설정)" : sRest.substring(0, nEnd);
}



// 전송 XML(hashkey='style') 안의 Footer 영역에서 excelCellType 을 읽는다.
//  · 반환 : { "footer" : w2:footer 의 값, "column" : Footer 첫번째 w2:column 의 값 }
scwin.getSentFooterCellType = function () {
    let sBody = (scwin.gVar.req === undefined) ? "" : (scwin.gVar.req.body || "");
    let nStart = sBody.indexOf("<w2:footer");
    if (nStart < 0) {
        return { "footer" : "(미전달)", "column" : "(미전달)" };
    }
    let nEnd = sBody.indexOf("</w2:footer>", nStart);
    let sFooterXml = (nEnd < 0) ? sBody.substring(nStart) : sBody.substring(nStart, nEnd);
    let sFooterTag = sFooterXml.substring(0, sFooterXml.indexOf(">"));

    let nCol = sFooterXml.indexOf("<w2:column");
    let sColumnTag = (nCol < 0) ? "" : sFooterXml.substring(nCol, sFooterXml.indexOf(">", nCol));

    return {
        "footer" : scwin.getAttrValue(sFooterTag, "excelCellType"),
        "column" : (sColumnTag === "") ? "(미전달)" : scwin.getAttrValue(sColumnTag, "excelCellType")
    };
}



// enum 값별 결과 출력
scwin.printEnumLine = function (nIndex, sEnum, sFormat, sSelected, sSentFooter) {
    let bIs = (sSelected === sEnum);
    wf_body_bottom.getObj("scwin").setReturnValue("[" + nIndex + "] " + sEnum + " 설정 여부 : " + bIs + (bIs ? (" / 전송 XML 의 footer excelCellType : " + sSentFooter + " (Excel 표시 형식 : " + sFormat + ")") : ""));
}



// advancedExcelDownload 실행 후 서버 전송값으로 확인
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let cExcelCellType = con_excelCellType.getValue();
    let cColumnExcelCellType = con_columnExcelCellType.getValue();

    let options = { "fileName" : "footer_excelCellType" };
    let vUseDataFormat = par_useDataFormat.getValue();
    if (vUseDataFormat !== "") {
        options.useDataFormat = vUseDataFormat;
    }

    scwin.gVar = {};
    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(options);
    } finally {
        scwin.gVar.unhook();
    }

    if (scwin.gVar.req.kind === "") {
        bottom.setReturnValue("요청 발생 : 없음 (다운로드 미실행)");
        return;
    }

    let objSent = scwin.getSentFooterCellType();

    bottom.setReturnValue("[1] 설정값 footer=" + ((cExcelCellType === '') ? '(미설정)' : cExcelCellType) + " / footer column=" + ((cColumnExcelCellType === '') ? '(미설정)' : cColumnExcelCellType) + " -> 전송 XML : footer=" + objSent.footer + " / footer column=" + objSent.column);
    scwin.printEnumLine(2, "text", "텍스트", cExcelCellType, objSent.footer);
    scwin.printEnumLine(3, "number", "숫자", cExcelCellType, objSent.footer);
    scwin.printEnumLine(4, "bigDecimal", "숫자", cExcelCellType, objSent.footer);
    scwin.printEnumLine(5, "date", "날짜", cExcelCellType, objSent.footer);
    bottom.setReturnValue("[6] 전송 useDataFormat : " + scwin.getSentValue("useDataFormat") + " / 전송 XML 의 footer column excelCellType : " + objSent.column);
}
